    constructor(C _c) { c = _c; }
    function run(uint fundAmount, uint amount) public payable {
        require(fundAmount <= address(this).balance);
        require(amount <= fundAmount);
        c.fallback{value: fundAmount}();
        uint balBefore = address(c).balance;
        uint cntBefore = c.depositsCount();
        c.sendMoney(address(c), amount);
        assert(c.depositsCount() == cntBefore + 1 && address(c).balance == balBefore);
    }
    receive() external payable {}
}

